"""
Fenwick Tree (BIT) による k 番目の値取得 & 動的中央値 (BIT k-th Element)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
値 x を add(x, 1) で度数分布に記録し、累積和が k 以上となる最小インデックスを O(log N) で二分探索 (ビット探索)。
平衡二分木 (std::set) の代わりに軽量・高速に k 番目に小さい要素を取得可能。
負の値や大きな値は座標圧縮 (compress) と併用。

【メソッド】
- add(p, x): インデックス p に x を加算 (O(log N))
- sum(l, r): 区間 [l, r) の和を計算 (O(log N))
- kth(k): 1-indexed で k 番目に小さい要素 (インデックス) を取得 (O(log N))
"""

# https://github.com/ddfkit/acsampl/blob/main/sorted.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class BIT:
    def __init__(self,n):
        self.n=n;self.d=[0]*(n+1);self.b=1<<(n.bit_length())
    def add(self,p,x=1):
        p+=1
        while p<=self.n:self.d[p]+=x;p+=p&-p
    def _sum(self,r):
        s=0
        while r>0:s+=self.d[r];r-=r&-r
        return s
    def sum(self,l,r):return self._sum(r)-self._sum(l)
    def kth(self,k):
        idx=0;d=self.b
        while d:
            nxt=idx+d
            if nxt<=self.n and self.d[nxt]<k:idx=nxt;k-=self.d[idx]
            d>>=1
        return idx

# https://github.com/ddfkit/acsampl/blob/main/sorted.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def compress(a):
    vals=sorted(set(a))
    mp={v:i for i,v in enumerate(vals)}
    return [mp[x] for x in a],vals

if __name__ == "__main__":
    bit = BIT(10)
    for x in [1, 1, 4, 5, 1, 4]: bit.add(x)
    assert bit.kth(1) == 1
    assert bit.kth(3) == 1
    assert bit.kth(4) == 4
    assert bit.kth(6) == 5

    arr = [100, 20, 50, 20]
    c_arr, vals = compress(arr)
    assert c_arr == [2, 0, 1, 0] and vals == [20, 50, 100]
    print("sorted.py: tests passed!")
